// JPA Repository method using aggregate functions
@Repository
public interface OrderRepository extends JpaRepository<Order, Long> {

    @Query("SELECT COUNT(o) FROM Order o WHERE o.status = :status")
    long countByStatus(String status);  // counts orders with given status

    @Query("SELECT SUM(o.amount) FROM Order o WHERE o.customerId = :customerId")
    Double totalSpentByCustomer(Long customerId);  // total amount spent

    @Query("SELECT AVG(o.amount) FROM Order o")
    Double averageOrderValue();  // mean order value

    @Query("SELECT MIN(o.orderDate), MAX(o.orderDate) FROM Order o")
    Object[] getDateRange();  // earliest and latest order dates

    @Query("SELECT o.category, COUNT(o), SUM(o.amount) " +
           "FROM Order o GROUP BY o.category")
    List<Object[]> statisticsByCategory();  // count and sum per category
}

// Using in a service
var totalOrders = orderRepository.count();  // COUNT(*)
var averageValue = orderRepository.averageOrderValue();  // AVG(amount)

// Entity with nullable fields
record Employee(Long id, String name, Integer salary, Integer bonus) {}

@Repository
public interface EmployeeRepository extends JpaRepository<Employee, Long> {

    // These queries show different NULL behaviors

    @Query("SELECT COUNT(*) FROM Employee e")
    long countAllEmployees();  // returns 5 even if all salaries are NULL

    @Query("SELECT COUNT(e.salary) FROM Employee e")
    long countEmployeesWithSalary();  // returns 3 if 2 have NULL salary

    @Query("SELECT AVG(e.bonus) FROM Employee e")
    Double averageBonus();  // ignores employees with NULL bonus

    // Treating NULL as zero explicitly
    @Query("SELECT AVG(COALESCE(e.bonus, 0)) FROM Employee e")
    Double averageBonusIncludingZeros();  // NULL becomes 0 before averaging

    @Query("SELECT SUM(COALESCE(e.bonus, 0)) FROM Employee e")
    Long totalBonusBudget();  // safe sum treating NULL as no bonus paid
}

// Results differ significantly
// If 5 employees with bonuses: [1000, NULL, 2000, NULL, 3000]
var avgIgnoringNull = repo.averageBonus();  // (1000+2000+3000)/3 = 2000
var avgTreatingAsZero = repo.averageBonusIncludingZeros();  // 6000/5 = 1200

// Order entity with customer relationship
record Order(Long id, Long customerId, String productCode, Double amount) {}

@Repository
public interface OrderRepository extends JpaRepository<Order, Long> {

    // Regular count vs distinct count
    @Query("SELECT COUNT(o.customerId) FROM Order o")
    long totalOrders();  // counts all orders, duplicates included

    @Query("SELECT COUNT(DISTINCT o.customerId) FROM Order o")
    long uniqueCustomers();  // counts how many different customers ordered

    @Query("SELECT COUNT(DISTINCT o.productCode) FROM Order o ")
    long uniqueProductsSold();  // how many different products were ordered

    // Group by with distinct count
    @Query("SELECT o.productCode, COUNT(DISTINCT o.customerId) " +
           "FROM Order o GROUP BY o.productCode")
    List<Object[]> uniqueCustomersPerProduct();  // distinct customers per product

    // Multiple distinct counts in one query
    @Query("SELECT COUNT(DISTINCT o.customerId), " +
           "COUNT(DISTINCT o.productCode) FROM Order o")
    Object[] getUniqueMetrics();  // [uniqueCustomers, uniqueProducts]
}

// Example: 100 orders from 25 customers buying 10 different products
var totalOrders = repo.totalOrders();  // returns 100
var uniqueCustomers = repo.uniqueCustomers();  // returns 25
